/// Supply 1000 BTC, borrow 100 BTC, utilization rate = 100 / 900, exchange rate = 900 / 1000
#[test]
fun test_reserve_basic_lifecycle_works() {
    let admin = @0xAD;
    let mut scenario_value = sui::test_scenario::begin(admin);

    let ctx = scenario_value.ctx();
    let mut reserve = new<MainMarket, BTC>(ctx, 1);

    let amount = 1000;
    let btc = sui::balance::create_for_testing<BTC>(amount).into_coin(ctx);
    let mut ctokens = reserve.mint_ctokens<MainMarket, BTC>(btc).into_coin(ctx);
    reserve.ensure_invariants_hold<MainMarket, BTC>();

    let mut borrowed_balance = reserve.borrow_amount<MainMarket, BTC>(100);
    reserve.ensure_invariants_hold<MainMarket, BTC>();

    assert!(borrowed_balance.value() == 100);
    assert!(reserve.cash == 900);
    assert!(reserve.debt.eq(float::from(100)));
    assert!(reserve.cash_reserve.is_zero());
    assert!(reserve.exchange_rate() == math::float::from_quotient(1, 1));
    assert!(reserve.util_rate() == float::from_quotient(1, 10));

    // no interest accrue at the moment
    std::unit_test::destroy(borrowed_balance.split(1));
    reserve.repay_amount(borrowed_balance.into_coin(ctx));
    reserve.ensure_invariants_hold<MainMarket, BTC>();

    assert!(reserve.cash == 999);
    assert!(reserve.debt == float::one());
    assert!(reserve.cash_reserve.is_zero());

    assert!(reserve.exchange_rate() == math::float::from_quotient(1, 1));
    assert!(reserve.util_rate() == float::from_quotient(1, 1000));

    let remaining = ctokens.split(10, ctx);
    // this is because there isn't as many cash in the pool as part of the cash goes to cash reserve
    std::unit_test::destroy(remaining);

    let btc = reserve.burn_ctokens<MainMarket, BTC>(ctokens);
    reserve.ensure_invariants_hold<MainMarket, BTC>();

    assert!(reserve.cash == 9);
    assert!(reserve.debt.eq(float::from(1)));
    assert!(reserve.cash_reserve.is_zero());

    assert!(btc.value() == 990);

    sui::balance::destroy_for_testing(btc);
    std::unit_test::destroy(reserve);
    scenario_value.end();
}

