    assert!(reserve.exchange_rate() == math::float::from_quotient(1, 1));
    assert!(reserve.util_rate().is_zero());

    assert!(loan.amount() == 100);

    let repay_btc = sui::balance::create_for_testing<BTC>(100).into_coin(ctx);
    let fee_btc = sui::balance::create_for_testing<BTC>(1).into_coin(ctx);
    reserve.repay_flash_loan(loan, repay_btc, fee_btc);
    reserve.ensure_invariants_hold<MainMarket, BTC>();

    assert!(reserve.cash == 1001);
    assert!(reserve.debt.is_zero());
    assert!(reserve.cash_reserve.eq(float::from(1)));
    assert!(reserve.exchange_rate() == math::float::from_quotient(1, 1));
    assert!(reserve.util_rate() == float::from_quotient(0, 1));

    std::unit_test::destroy(ctokens);
    std::unit_test::destroy(borrowed_balance);
    std::unit_test::destroy(reserve);
    scenario_value.end();
}

